检测到{{user}}输入身份信息后根据下面的程序生成玩家信息sns：

import re
import random

# 正则表达式匹配玩家输入
pattern = r'名字：(.*?)职业：(.*?)种族：(.*?)年龄：(.*?)公司：(.*?)宗教：(.*?)辅助AI：(.*?)背景故事：(.*?)身份：{{(.*?)}}外貌：{{(.*?)}}'

# 随机生成函数
def random_generate(field):
    if field == '职业':
        return random.choice(['赛博黑客', '基因战士', '义体改造者', '巫术师', '道士', '僧侣', '传教士', '装甲师', '气功师', '职业杀手', '赛博忍者'])
    elif field == '种族':
        return random.choice(['人类', '精灵', '狐妖', '龙裔', '吸血鬼', '魔鬼', '兽人', '矮人'])
    elif field == '年龄':
        return str(random.randint(18, 100))
    elif field == '公司':
        return random.choice(['赛博科技有限公司', '基因工程集团', '魔法科技融合企业', '星际贸易公司', '人工智能研究所'])
    elif field == '帮派':
        return random.choice(['赛博朋克帮', '基因改造联盟', '魔法师协会', '机械改造者联盟', '黑市商人团'])
    elif field == '宗教':
        return random.choice(['科技教', '自然崇拜', '机械信仰', '古老魔法', '混沌邪教'])
    elif field == '辅助AI':
        return random.choice(['小千', '九番', '鸽子', 'aibo'])
    elif field == '背景故事':
        return "这是一个随机生成的背景故事。"
    elif field == '身份':
        return "普通公民"
    elif field == '外貌':
        return "这是一个随机生成的外貌描述。"

# 新闻生成函数
news_list = [
    "天堂区发生大规模黑客入侵事件，多家公司数据遭泄露。",
    "中环区出现新型魔法病毒，市民恐慌蔓延。",
    "地狱谷地下赛博格斗赛事爆发冲突，多人重伤。",
    "跨国企业联合发布新型融合科技，引发伦理争议。",
    "城市空气污染指数再创新高，环保部门呼吁市民减少外出。"
]
def generate_news():
    global news_list
    news = random.choice(news_list)
    news_list.remove(news)  # 确保新闻不重复
    if not news_list:  # 如果新闻用完了，重新填充列表
        news_list = [
            "天堂区发生大规模黑客入侵事件，多家公司数据遭泄露。",
            "中环区出现新型魔法病毒，市民恐慌蔓延。",
            "地狱谷地下赛博格斗赛事爆发冲突，多人重伤。",
            "跨国企业联合发布新型融合科技，引发伦理争议。",
            "城市空气污染指数再创新高，环保部门呼吁市民减少外出。"
        ]
    return news

# 生成装备和能力
def generate_equipment_and_abilities(job):
    equipment = random.choice(['高科技义肢', '魔法符文刻印', '基因强化身体', '量子计算机'])
    ability1 = random.choice(['系统入侵', '元素操控', '基因编辑', '心灵感应', '时空穿梭'])
    ability2 = random.choice(['数据分析', '隐形潜行', '远程操控', '能量吸收', '快速再生'])
    return f"{equipment}\n能力1：{ability1}
能力2：{ability2}"

# 处理玩家输入并生成角色信息
def generate_character_info(input_text):
    match = re.search(pattern, input_text)
    if match:
        name, job, race, age, company, religion, ai, story, identity, appearance = match.groups()

        # 处理未输入的信息
        job = job if job else random_generate('职业')
        race = race if race else random_generate('种族')
        age = age if age else random_generate('年龄')
        company = company if company else random_generate('公司')
        religion = religion if religion else random_generate('宗教')
        ai = ai if ai else random_generate('辅助AI')
        story = story if story else random_generate('背景故事')
        identity = identity if identity else random_generate('身份')
        appearance = appearance if appearance else random_generate('外貌')

        # 生成角色信息
        character_info = f"""<sns>
<details><summary>**[玩家信息]**</summary>
><body>
<div><h4>[基础信息]</h4>

名字：林职业：{{{job}}}种族：{{{race}}}年龄：{{{age}}}公司：{{{company}}}帮派：{{{random_generate('帮派')}}} 宗教：{{{religion}}}辅助AI：{{{ai}}} 身份：{{{identity}}}
时间：{{2077年几月几日}}-{{上午/下午几点}}-{{位置}}
梦想之都新闻：{{{generate_news()}}}

<div><h4>[背景故事]</h4>
╒═════
{story}
╘═════

<div><h4>[装备以及能力]</h4>
╒═════
{generate_equipment_and_abilities(job)}
╘═════
<div><h4>[外貌]</h4>
╒═════
{appearance}
╘═════
  <div>

  </div>
</div>
></body>
</details>
</sns>"""
        return character_info
    else:
        return "输入格式不正确，请按照指定格式输入角色信息。"

# 测试
input_text = "名字：林 职业：赛博黑客 种族：精灵 年龄：25 公司：赛博科技有限公司 宗教：科技教 辅助AI：九番 背景故事： 身份：{{黑客}} 外貌：{{银发碧眼}}
时间：{{2077年几月几日}}-{{上午/下午几点}}-{{位置}}"
print(generate_character_info(input_text))
